// The cost of one routed call on both sides. Taifoon charges the list price on the key (taifoon.usd_per_1m, USD per 1M tokens);
// NEAR records the call in its own usage at the price its row carries (the same numbers when written by workflow 20).
const r = $('One call').first().json; const list = $('List models').first().json.data ?? [];
const m = list.find((x) => x.id === r.model) ?? {}; const p = m.taifoon?.usd_per_1m ?? {}; const inP = Number(p.in ?? 0), outP = Number(p.out ?? 0);
const u = r.usage ?? {}; const cost = ((u.prompt_tokens ?? 0) * inP + (u.completion_tokens ?? 0) * outP) / 1e6;
return [{ json: { model: r.model, answer: r.choices?.[0]?.message?.content ?? null, usage: u, list_price_usd_per_mtok: { in: inP, out: outP }, cost_usd_at_list: Number(cost.toFixed(9)), charged_by_taifoon: r.taifoon?.sale ? { usdc: r.taifoon.sale.usdc, sale_id: r.taifoon.sale.id } : null, evidence: r.taifoon?.sale?.id ?? r.id ?? null } }];
